html_files = []
for root, _, files in os.walk(FRONTEND_DIR):
    for file in files:
        if file.endswith('.html'):
            html_files.append(os.path.join(root, file))

for filepath in html_files:
    with open(filepath, 'r', encoding='utf-8') as f:
        html = f.read()
    
    soup = BeautifulSoup(html, 'html.parser')
    modified = False
    
    # Target all typical nav links
    nav_links = soup.find_all('a', class_=re.compile(r'nav-link.*'))
    for link in nav_links:
        # Check if already contains SVG
        if link.find('svg'):
            continue
            
        text = link.get_text()
        
        # Determine the correct SVG icon based on text matching
        lower_text = text.lower()
        matched_svg = svg_map['default']
        for key, svg in svg_map.items():
            if key in lower_text:
                matched_svg = svg
                break
                
        # Remove any emojis
        # Instead of parsing the child nodes, we just replace emojis in text nodes
        has_emoji = False
        for child in link.children:
            if child.name is None: # NavigableString
                old_str = str(child)
                new_str = ''.join(c for c in old_str if not is_emoji(c))
                if old_str != new_str:
                    child.replace_with(new_str)
                    has_emoji = True
        
        # Sometimes emojis are in spans or other children
        for span in link.find_all('span'):
            old_str = span.string
            if old_str:
                new_str = ''.join(c for c in old_str if not is_emoji(c))
                if old_str != new_str:
                    span.string = new_str
                    has_emoji = True
                    
        # Now prepend the SVG to the link
        # We can create a BeautifulSoup tag from the SVG string
        svg_soup = BeautifulSoup(matched_svg, 'html.parser')
        link.insert(0, svg_soup)
        modified = True

    if modified:
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(str(soup))
            
print("Successfully replaced emojis with SVGs in navigation links.")
